func cocoon_table_index(index uint64, length int) int {
	if index >= uint64(length) {
		panic("out of bounds table access")
	}
	return int(index)
}
func cocoon_table_slice(table []any, low, high uint64) []any {
	if low > high ||
		high > uint64(len(
			table,
		)) {
		panic("out of bounds table access")
	}
	return table[low:high:len(table)]
}
